/// <summary>
/// Group of cost centers, used on the Group level of the indirect cost matrix.
/// </summary>
public class HOGpmaCostCenterGroup extends common
{
}

Method.Source:
/// <summary>
/// Finds a cost center group.
/// </summary>
/// <param name = "_costCenterGroupId">The group ID.</param>
/// <param name = "_forUpdate">true to select the record for update.</param>
/// <returns>The group, or an empty buffer.</returns>
public static HOGpmaCostCenterGroup find(HOGpmaCostCenterGroupId _costCenterGroupId, boolean _forUpdate = false)
{
    HOGpmaCostCenterGroup costCenterGroup;

    if (_costCenterGroupId)
    {
        costCenterGroup.selectForUpdate(_forUpdate);

        select firstonly costCenterGroup
            where costCenterGroup.CostCenterGroupId == _costCenterGroupId;
    }

    return costCenterGroup;
}

/// <summary>
/// Checks whether a cost center group exists.
/// </summary>
/// <param name = "_costCenterGroupId">The group ID.</param>
/// <returns>true if the group exists; otherwise, false.</returns>
public static boolean exist(HOGpmaCostCenterGroupId _costCenterGroupId)
{
    return _costCenterGroupId
        && (select firstonly RecId from HOGpmaCostCenterGroup
                where HOGpmaCostCenterGroup.CostCenterGroupId == _costCenterGroupId).RecId != 0;
}

/// <summary>
/// Prevents deleting a group that the indirect cost matrix still uses.
/// </summary>
/// <returns>true if the group can be deleted; otherwise, false.</returns>
public boolean validateDelete()
{
    boolean ret = super();

    if (ret)
    {
        HOGpmaIndirectCostMatrix matrix;

        select firstonly RecId from matrix
            where matrix.CostCenterCode     == TableGroupAll::GroupId
               && matrix.CostCenterRelation == this.CostCenterGroupId;

        if (matrix.RecId)
        {
            ret = checkFailed(strFmt("@HOGpma:ErrGroupInUse", this.CostCenterGroupId));
        }
    }

    return ret;
}
